create extension if not exists "pgcrypto";
create type public.profile_status as enum ('ACTIVE','SUSPENDED','DISABLED');
create type public.question_status as enum ('OPEN','ANSWERED','RESOLVED','CLOSED','REMOVED');
create type public.user_role as enum ('USER','MODERATOR','ADMIN');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null, username text unique not null, avatar_url text, bio text, course text, semester integer, university_registration text, reputation_score integer not null default 0, answers_count integer not null default 0, accepted_answers_count integer not null default 0, average_rating numeric(3,2) not null default 0, ratings_count integer not null default 0, status public.profile_status not null default 'ACTIVE', last_seen_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.user_roles (user_id uuid references public.profiles(id) on delete cascade, role public.user_role not null default 'USER', created_at timestamptz not null default now(), primary key (user_id, role));
create table public.subjects (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, description text, code text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tags (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, description text, active boolean not null default true, created_at timestamptz not null default now());
create table public.questions (id uuid primary key default gen_random_uuid(), author_id uuid not null references public.profiles(id), subject_id uuid not null references public.subjects(id), title text not null check (char_length(title) between 12 and 140), body text not null check (char_length(body) between 30 and 10000), status public.question_status not null default 'OPEN', views_count integer not null default 0, answers_count integer not null default 0, accepted_answer_id uuid, last_activity_at timestamptz not null default now(), deleted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index questions_feed_idx on public.questions(status, last_activity_at desc); create index questions_author_idx on public.questions(author_id); create index questions_subject_idx on public.questions(subject_id);
create table public.question_tags (question_id uuid references public.questions(id) on delete cascade, tag_id uuid references public.tags(id) on delete restrict, primary key(question_id, tag_id));
create table public.answers (id uuid primary key default gen_random_uuid(), question_id uuid not null references public.questions(id) on delete cascade, author_id uuid not null references public.profiles(id), body text not null check (char_length(body) between 10 and 10000), score integer not null default 0, ratings_count integer not null default 0, is_accepted boolean not null default false, deleted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.questions add constraint questions_accepted_answer_fk foreign key (accepted_answer_id) references public.answers(id) on delete set null;
create unique index one_accepted_answer_per_question on public.answers(question_id) where is_accepted = true;
create table public.answer_ratings (id uuid primary key default gen_random_uuid(), answer_id uuid not null references public.answers(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, rating integer not null check(rating between 1 and 5), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(answer_id,user_id));
create table public.reputation_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id), source_type text not null, source_id uuid, points integer not null, reason text not null, created_at timestamptz not null default now());
create table public.badges (id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, description text not null, icon text, active boolean not null default true, created_at timestamptz not null default now());
create table public.user_badges (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, badge_id uuid not null references public.badges(id) on delete cascade, awarded_at timestamptz not null default now(), unique(user_id,badge_id));
create table public.conversations (id uuid primary key default gen_random_uuid(), type text not null default 'DIRECT' check(type in ('DIRECT','GROUP')), question_id uuid references public.questions(id), created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), last_message_at timestamptz);
create table public.conversation_members (conversation_id uuid references public.conversations(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, joined_at timestamptz not null default now(), last_read_at timestamptz, archived_at timestamptz, primary key(conversation_id,user_id));
create table public.messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, sender_id uuid not null references public.profiles(id), body text not null check(char_length(body) between 1 and 10000), created_at timestamptz not null default now(), edited_at timestamptz, deleted_at timestamptz); create index messages_conversation_idx on public.messages(conversation_id, created_at);
create table public.reports (id uuid primary key default gen_random_uuid(), reporter_id uuid not null references public.profiles(id), target_type text not null, target_id uuid not null, reason text not null, description text, status text not null default 'OPEN', reviewed_by uuid references public.profiles(id), reviewed_at timestamptz, resolution_notes text, created_at timestamptz not null default now()); create unique index reports_deduplicate on public.reports(reporter_id,target_type,target_id) where status in ('OPEN','UNDER_REVIEW');
create table public.moderation_actions (id uuid primary key default gen_random_uuid(), moderator_id uuid not null references public.profiles(id), target_type text not null, target_id uuid not null, action text not null, reason text not null, report_id uuid references public.reports(id), created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, type text not null, actor_id uuid references public.profiles(id), entity_type text, entity_id uuid, title text not null, body text, read_at timestamptz, created_at timestamptz not null default now()); create index notifications_user_idx on public.notifications(user_id,created_at desc);
alter table public.profiles enable row level security; alter table public.questions enable row level security; alter table public.answers enable row level security; alter table public.answer_ratings enable row level security; alter table public.conversations enable row level security; alter table public.conversation_members enable row level security; alter table public.messages enable row level security; alter table public.notifications enable row level security; alter table public.reports enable row level security;
create policy "public profiles are readable" on public.profiles for select using (status = 'ACTIVE'); create policy "users update own profile" on public.profiles for update using (auth.uid() = id); create policy "questions are readable" on public.questions for select using (deleted_at is null and status <> 'REMOVED'); create policy "authenticated users create questions" on public.questions for insert with check (auth.uid() = author_id); create policy "authors update questions" on public.questions for update using (auth.uid() = author_id); create policy "answers are readable" on public.answers for select using (deleted_at is null); create policy "authenticated users answer" on public.answers for insert with check (auth.uid() = author_id); create policy "authors update answers" on public.answers for update using (auth.uid() = author_id); create policy "members read conversations" on public.conversations for select using (exists(select 1 from public.conversation_members m where m.conversation_id = id and m.user_id = auth.uid())); create policy "members read messages" on public.messages for select using (exists(select 1 from public.conversation_members m where m.conversation_id = conversation_id and m.user_id = auth.uid())); create policy "members send messages" on public.messages for insert with check (auth.uid() = sender_id and exists(select 1 from public.conversation_members m where m.conversation_id = conversation_id and m.user_id = auth.uid())); create policy "owners read notifications" on public.notifications for select using (auth.uid() = user_id); create policy "users create reports" on public.reports for insert with check (auth.uid() = reporter_id); create policy "reporters read reports" on public.reports for select using (auth.uid() = reporter_id);
